BEGIN;
ALTER TABLE organization_settings ADD COLUMN task_categories text[] NOT NULL DEFAULT '{}',ADD COLUMN project_categories text[] NOT NULL DEFAULT '{}';
CREATE TABLE organization_holidays(id uuid PRIMARY KEY,organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE RESTRICT,title varchar(160) NOT NULL,starts_on date NOT NULL,ends_on date NOT NULL,version integer NOT NULL DEFAULT 1 CHECK(version>0),created_by_id uuid NOT NULL,archived_at timestamptz(3),created_at timestamptz(3) NOT NULL DEFAULT now(),UNIQUE(organization_id,id),FOREIGN KEY(organization_id,created_by_id) REFERENCES memberships(organization_id,id) ON DELETE RESTRICT,CHECK(ends_on>=starts_on AND ends_on-starts_on<=365));
CREATE INDEX organization_holidays_organization_id_archived_at_starts_on_ends_on_idx ON organization_holidays(organization_id,archived_at,starts_on,ends_on);
CREATE TABLE organization_branding(organization_id uuid PRIMARY KEY REFERENCES organizations(id) ON DELETE RESTRICT,logo_version_id uuid,version integer NOT NULL DEFAULT 1 CHECK(version>0),updated_by_id uuid NOT NULL,updated_at timestamptz(3) NOT NULL,FOREIGN KEY(organization_id,logo_version_id) REFERENCES document_versions(organization_id,id) ON DELETE RESTRICT,FOREIGN KEY(organization_id,updated_by_id) REFERENCES memberships(organization_id,id) ON DELETE RESTRICT);
ALTER TABLE organization_holidays ENABLE ROW LEVEL SECURITY;ALTER TABLE organization_holidays FORCE ROW LEVEL SECURITY;
CREATE POLICY holiday_read ON organization_holidays FOR SELECT TO work_app USING(organization_id=NULLIF(current_setting('app.organization_id',true),'')::uuid AND public.work_is_member());
CREATE POLICY holiday_insert ON organization_holidays FOR INSERT TO work_app WITH CHECK(organization_id=NULLIF(current_setting('app.organization_id',true),'')::uuid AND public.work_integration_manager() AND public.ai_owns_member(created_by_id));
CREATE POLICY holiday_update ON organization_holidays FOR UPDATE TO work_app USING(organization_id=NULLIF(current_setting('app.organization_id',true),'')::uuid AND public.work_integration_manager()) WITH CHECK(organization_id=NULLIF(current_setting('app.organization_id',true),'')::uuid AND public.work_integration_manager());
GRANT SELECT,INSERT,UPDATE ON organization_holidays TO work_app;REVOKE DELETE,TRUNCATE ON organization_holidays FROM work_app;
ALTER TABLE organization_branding ENABLE ROW LEVEL SECURITY;ALTER TABLE organization_branding FORCE ROW LEVEL SECURITY;
CREATE POLICY branding_read ON organization_branding FOR SELECT TO work_app USING(organization_id=NULLIF(current_setting('app.organization_id',true),'')::uuid AND public.work_is_member());
CREATE POLICY branding_insert ON organization_branding FOR INSERT TO work_app WITH CHECK(organization_id=NULLIF(current_setting('app.organization_id',true),'')::uuid AND public.work_integration_manager() AND public.ai_owns_member(updated_by_id));
CREATE POLICY branding_update ON organization_branding FOR UPDATE TO work_app USING(organization_id=NULLIF(current_setting('app.organization_id',true),'')::uuid AND public.work_integration_manager()) WITH CHECK(organization_id=NULLIF(current_setting('app.organization_id',true),'')::uuid AND public.work_integration_manager() AND public.ai_owns_member(updated_by_id));
GRANT SELECT,INSERT,UPDATE ON organization_branding TO work_app;REVOKE DELETE,TRUNCATE ON organization_branding FROM work_app;
COMMIT;
